CRMDashboard = {
    init: async function (app, container) {
        container = container || $('.component[name=CRMDashboard]');
        var cards = $('[data-crm-count]', container);
        await Promise.all(cards.map(async function () {
            var card = $(this);
            try {
                var result = await api.get('ClientRelationshipManagement/' + card.data('crm-count') + '?$count=true&$top=0');
                card.text(result['@odata.count'] ?? (result.value || []).length);
            } catch (_) {
                card.text('Unavailable');
                card.closest('.crm-summary-card').addClass('is-unavailable');
            }
        }).get());
    }
}
